const levels = [
  {name:'黑礁登陆',story:'停役的最后一夜，一人来拆灯机，一人来收电台。林澈刚把扬声器里的水倒出来，海雁号船长梁青就报了人数。渡轮主机停车，救援艇还在外海。两人得先穿过防潮门，赶在船漂入礁区前恢复联络。',quote:'梁青：“四十一位，算上我。”林澈：“听见了。”沈遥按住他的手：“你没按发话键。她不知道。”',after:'梁青终于听见岸上回话。她留着一次应急推进的电量，要等能看清船位才用。'},
  {name:'失电码头',story:'电缆在码头上泡了一夜。林澈要找出还能送电的一路，沈遥得接起能让海上听清的发报线。船上传来第二个声音，水手阿棠在后甲板看见了旧绿标，梁青从驾驶台还看不见。',quote:'沈遥：“别替他重复。请把电台递过去，让我听他讲。”',after:'岸电稳定。六天前两人签过的交接单上，「北线」一栏盖着可用章。'},
  {name:'双路回电',story:'旧绿标独自亮着，渡轮没法定出方向；两盏灯连成一线，才像一条航道。六天前的交接单在手，林澈决定给塔上的引导灯合闸，沈遥去电台报告恢复。',quote:'林澈：“我们那天验过。”沈遥：“我也签过。我来回她。”',after:'梁青复述「北线可以进入」，船头随第二盏绿灯向碎浪偏去。林澈当即遮住灯，沈遥叫停。船止住偏转，却已漂进内流。'},
  {name:'灯下暗室',story:'错灯灭了。要知道船还有哪一条路可走，两人得把潮水从档案室排出去。水面漂着只搪瓷杯，杯底写着他们小时候的名字。那时他们喜欢互录十秒怪响，给对方猜。',quote:'梁青：“我带她等下一道浪。你们找到什么就说什么。”',after:'水退到柜门以下。柜顶一盒是值班录音，另一盒是两个孩子合录的《十秒钟北岬》。'},
  {name:'十三年前',story:'放错的带子里，小女孩叫男孩猜一阵哐啷声。林澈还记得答案。换回值班录音后，两轨总差一点：一端是灯机闭合，另一端有人坚持要再测一次潮。',quote:'沈遥：“先别替我妈补那半句话。把机器声往后移一点，再听。”',after:'两轨对齐。继电器响过，测潮员还没给出通航结论。录音末尾留下原始草图的柜号。'},
  {name:'被划掉的坐标',story:'把灯机验收联放回潮图上，两张纸的订孔能正好对上。裁掉的边角写着「北线待测」。更让林澈难堪的是，六天前他也只验了灯，沈遥导出的交接单上却只印出了「可用」。他当时看见了。',quote:'沈遥：“我自己按的确认。”林澈：“我在备注该在的地方划了一下，没让你重打。”',after:'沈遥告诉海雁号，他们还不能确定哪条路可走。梁青把电台交给阿棠，请他从船尾独立报出礁影。'},
  {name:'断桥上方',story:'岸上的上标尺在断桥对面，下标尺在浪里。林澈得把沈遥先送过去，再让她把桥接稳。第一次换手之后，林澈终于能松开绞盘，也有空听一听吊篮里螺丝滚动的声音。',quote:'沈遥：“铁皮饼干盒。那道题我早猜出来了，想听你再放一次。”',after:'桥头柜里有一份父母当年共同写下的更正稿。收件人一栏空着。沈遥把他们六天前的交接单也夹了进去。'},
  {name:'未寄出的报告',story:'中继随时会被风吹偏。沈遥原本准备先读十三年前的旧稿，林澈把新单子翻到最上面。海上的人还在按照这张单子找路。第一句由他自己说。',quote:'林澈：“灯机是我验的，我只验了灯机。”沈遥：“把它说成北线恢复的人是我。”',after:'梁青逐句复述。阿棠从船尾补报：白浪后面，有时会露出一根断掉的旧桩。岸上和驾驶台都看不见它。'},
  {name:'潮位校验',story:'旧潮图给出两条看似可行的槽线。其中一条在落潮时会露出槽底的碎石。两人要在同一道浪里读上下标尺，再用阿棠报来的断桩核对方向。少了船上的眼睛，地图只能排除一半的错误。',quote:'梁青：“我窗前两道浪一模一样。阿棠，你那儿呢？”',after:'同一根断桩在两个角度下对上了。侧槽仍能通行，转向点却已移出主透镜原来的光带。'},
  {name:'裂纹透镜',story:'主透镜裂成两道光，林澈从机械背板看不见重影。沈遥得站到外环，看哪一道落在新测的水线上。调焦时他们交换判断的位置，让另一人也亲眼看一次。',quote:'梁青：“现在只有一条了。别动，我想再看一眼。”',after:'海面终于出现一道窄光。雨帘仍会遮住它，三人约定用额外的声响提醒驾驶台去看。'},
  {name:'无光的三秒',story:'这次只演练。三声短响提醒梁青查看光带，何时转由她决定。第一次试响，塔上仪表全亮了，阿棠也听齐了；梁青却从驾驶台报回两声。两人得改变间隔，再等一轮回话。',quote:'沈遥：“你收到了几声，就报几声。我们等。”',after:'第二轮，驾驶台把三声复述完整。阿棠回到船尾等断桩露头，梁青守在应急推进开关旁。'},
  {name:'航道重现',story:'海雁号进入窄光。林澈要守住方位，沈遥要等他稳住再发送约定的声音。岸上两块表都亮了，梁青仍多等了一拍。她在等一个只有船尾才能看见的东西。',quote:'梁青：“别替我倒数。我听见就会回你。”',after:'阿棠喊出「桩出来了」。梁青回话：「北岬，我看见了。现在我转。」最后一次应急推进带船驶入背风水。电台先传来接缆声，再传来四十一个人的点名。'},
];

